  --accent: #00b4d8;
  --accent-2: #0077b6;
  --success: #37d67a;
  --danger: #ff6b6b;
  --border: rgba(255,255,255,0.14);
  --shadow: 0 12px 34px rgba(0,0,0,0.35);
  --radius: 14px;
  --container: 1160px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;
  background: linear-gradient(180deg, #0d1b2a 0%, #111f30 60%, #0f1a28 100%);
  color: var(--text);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
.container { width: min(100% - 2rem, var(--container)); margin: 0 auto; }
.section { padding: 72px 0; }
.section-tight { padding: 48px 0; }
.muted { color: var(--muted); }

.header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  background: rgba(13, 27, 42, 0.88);
  backdrop-filter: blur(10px);
}
.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 72px;
}
.brand { display: flex; align-items: center; gap: .75rem; font-weight: 700; }
.brand-badge {
  width: 34px; height: 34px; border-radius: 10px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  display: grid; place-items: center; color: #001722; font-weight: 800;
}
.nav-links { display: flex; align-items: center; gap: 1.2rem; }
.nav-link { color: #d5dfeb; font-weight: 500; }
.nav-link:hover { color: #fff; }
.dropdown { position: relative; }
.dropdown-toggle { cursor: pointer; }
.dropdown-menu {
  position: absolute; top: 140%; left: 0;
  min-width: 220px; border: 1px solid var(--border);
  background: #15273a; border-radius: 12px;
  box-shadow: var(--shadow); padding: .45rem;
  opacity: 0; visibility: hidden; transform: translateY(6px);
  transition: all .2s ease;
}
.dropdown:hover .dropdown-menu,
.dropdown:focus-within .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: .65rem .75rem; border-radius: 8px; color: #d5dfeb;
}
.dropdown-menu a:hover { background: #1e3348; color: #fff; }

.btn {
  border: none; border-radius: 10px; padding: .72rem 1rem;
  font-weight: 600; cursor: pointer; transition: .2s ease;
}
.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #02151f;
}
.btn-primary:hover { filter: brightness(1.08); transform: translateY(-1px); }
.btn-outline {
  border: 1px solid var(--border); color: var(--text); background: transparent;
}

.hero {
  padding: 88px 0 64px;
  display: grid; grid-template-columns: 1.1fr .9fr; gap: 2rem; align-items: center;
