.h1 { font-size: clamp(2rem, 3.4vw, 3.25rem); line-height: 1.15; margin: 0 0 1rem; }
.subhead { font-size: 1.05rem; color: var(--muted); max-width: 62ch; }
.hero-actions { display: flex; gap: .75rem; margin-top: 1.2rem; flex-wrap: wrap; }

.card {
  background: linear-gradient(180deg, rgba(31,50,70,.9), rgba(22,36,52,.95));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.p-24 { padding: 24px; }
.p-18 { padding: 18px; }

.diagram-grid {
  display: grid; grid-template-columns: repeat(3,1fr); gap: .8rem; align-items: center;
}
.diagram-node {
  background: #193047;
  border: 1px solid rgba(0,180,216,.32);
  border-radius: 10px;
  text-align: center;
  padding: .7rem .5rem;
  color: #cde8f0;
  font-size: .92rem;
}
.diagram-core {
  grid-column: 2 / 3;
  background: linear-gradient(145deg, #00b4d8, #0077b6);
  color: #01202f;
  font-weight: 700;
}

.tabs { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1rem; }
.tab {
  padding: .55rem .8rem; border-radius: 999px;
  border: 1px solid var(--border); background: #182b3f; color: #bfd0df;
  cursor: pointer; font-weight: 600;
}
.tab[aria-selected="true"] { background: linear-gradient(135deg, #00b4d8, #0077b6); color: #032130; border-color: transparent; }
.tab-panels > [data-panel] { display: none; }
.tab-panels > [data-panel].active { display: block; animation: fade .25s ease; }
@keyframes fade { from { opacity: .35; transform: translateY(4px); } to { opacity: 1; transform: none; } }

.grid-3 { display:grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.grid-2 { display:grid; grid-template-columns: repeat(2,1fr); gap: 1rem; }
.use-case { padding: 18px; border-radius: 12px; border: 1px solid var(--border); background:#18293b; }
.use-case h4 { margin: 0 0 .45rem; }
.link-chip { color: #85e8ff; font-size: .9rem; }

.accordion-item { border-top: 1px solid var(--border); }
.acc-btn {
  width: 100%; text-align: left; background: none; border: none; color: #eff6ff;
  padding: .95rem .2rem; font-size: 1rem; font-weight: 600; cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
}
.acc-panel { display: none; padding: 0 0 1rem; color: var(--muted); }
.accordion-item.active .acc-panel { display: block; }

.stats { display:grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.stat-circle {
  aspect-ratio: 1/1; border-radius: 50%;
  border: 8px solid #1f4f6b;
  background: radial-gradient(circle at 30% 20%, #274f69 0%, #13283b 70%);
  display:grid; place-items:center; text-align:center; padding: 1rem;
}
.stat-circle strong { display:block; font-size: 1.65rem; color: #8be9ff; }

.timeline-item { margin-bottom: .9rem; }
.progress {
  height: 9px; background: #152737; border-radius: 999px; overflow: hidden; margin-top: .35rem;
}
.progress > span {
  display:block; height:100%; background: linear-gradient(90deg, #00b4d8, #0077b6);
}

.carousel-track { display:grid; grid-template-columns: repeat(3, 1fr); gap: .8rem; }
.testimonial { background:#182a3d; border:1px solid var(--border); border-radius: 12px; padding: 1rem; }
.carousel-dots { display:flex; gap:.4rem; justify-content:center; margin-top:.8rem; }
.dot { width:10px; height:10px; border-radius:50%; background:#33516d; border:none; cursor:pointer; }
.dot.active { background:#00b4d8; }

.list-check { list-style:none; padding:0; margin:0; }
.list-check li { position:relative; padding-left:1.5rem; margin-bottom:.55rem; color:#d6e5f4; }
.list-check li::before { content:"✓"; position:absolute; left:0; color:#6de8ff; font-weight:700; }

.form-grid { display:grid; grid-template-columns: repeat(2,1fr); gap: .8rem; }
.field { display:flex; flex-direction:column; gap:.35rem; }
label { font-size:.9rem; color:#c2d4e6; }
input, select, textarea {
  width:100%; padding:.68rem .72rem; border-radius:10px;
  border:1px solid var(--border); background:#122232; color:#ebf4ff;
}
textarea { min-height: 120px; resize: vertical; }
.error { color: var(--danger); font-size:.8rem; min-height: 1em; }
.success-msg { color: var(--success); font-weight:600; }

.cookie-banner {
  position: fixed; left: 1rem; right: 1rem; bottom: 1rem;
  border: 1px solid var(--border); background: rgba(20,34,49,.96);
  border-radius: 12px; padding: .85rem 1rem; z-index: 80;
  display: flex; gap: .8rem; justify-content: space-between; align-items: center;
}
.cookie-banner.hidden { display:none; }

.footer { border-top:1px solid rgba(255,255,255,.08); padding: 22px 0 34px; color:#a2b6ca; }

@media (max-width: 980px) {
  .hero { grid-template-columns: 1fr; }
  .grid-3, .stats, .carousel-track { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .nav { min-height: 64px; }
  .nav-links { gap: .75rem; font-size: .95rem; }
  .grid-3, .grid-2, .stats, .carousel-track, .form-grid { grid-template-columns: 1fr; }
  .cookie-banner { flex-direction: column; align-items: flex-start; }
}
